	}

	public void setUseIn(List<MethodNode> useIn) {
		this.useIn = useIn;
	}

	@Override
	public AnnType getAnnType() {
		return AnnType.METHOD;
	}

	@Override
	public int hashCode() {
		return mthInfo.hashCode();
	}

	@Override
	public boolean equals(Object obj) {
		if (this == obj) {
			return true;
		}
		if (obj == null || getClass() != obj.getClass()) {
